  function applyLineOp(op) {
    const doc2 = view.state.doc;
    const head = view.state.selection.main.head;
    const line = doc2.lineAt(head);
    const idx = line.number - 1;
    const col = head - line.from;
    const lines = [];
    for (let i2 = 1; i2 <= doc2.lines; i2++)
      lines.push(doc2.line(i2).text);
    const plan = planLineOp(lines, idx, op);
    if (!plan) return;
    let anchor = 0;
    for (let i2 = 0; i2 < plan.idx; i2++)
      anchor += plan.lines[i2].length + 1;
    anchor += Math.min(col, plan.lines[plan.idx].length);
    view.dispatch({
      changes: {
        from: 0,
        to: doc2.length,
        insert: plan.lines.join("\n")
      },
      selection: { anchor }
    });
    view.focus();
  }
  $("lineDup").onclick = () => applyLineOp("dup");
